// This file is automatically generated. Do not edit it directly.
// v2
import { createClient } from '@supabase/supabase-js';
import type { Database } from './types';
import { traduciErrorePostgrest } from "@/lib/userErrorMessage";
import { authStorage } from "./authStorage";

const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL;
const SUPABASE_PUBLISHABLE_KEY = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY;
const SUPABASE_REST_TIMEOUT_MS = 25_000;
// v8.5 — Edge function generate-render ora risponde 202 in 2-3s e prosegue
// in background (EdgeRuntime.waitUntil). 60s e' abbondante per la parte
// sync (auth + validation + deduct credit + idempotency check + mark
// processing). Il render finale arriva via polling su render_sessions —
// nessun timeout long-running piu' sul client.
const SUPABASE_FUNCTION_TIMEOUT_MS = 60_000;

// Sicurezza: le variabili d'ambiente sono obbligatorie — nessun fallback hardcoded
if (!SUPABASE_URL || !SUPABASE_PUBLISHABLE_KEY) {
  throw new Error(
    "[Supabase] Variabili d'ambiente mancanti: VITE_SUPABASE_URL e VITE_SUPABASE_PUBLISHABLE_KEY sono obbligatorie. Controlla il file .env."
  );
}

// Import the supabase client like this:
// import { supabase } from "@/integrations/supabase/client";

function getRequestTimeout(input: RequestInfo | URL): number {
  const url = typeof input === "string"
    ? input
    : input instanceof URL
      ? input.toString()
      : input.url;

  // Le edge function AI possono legittimamente impiegare piu tempo.
  // Le query REST/RPC invece non devono lasciare il portale bloccato per un minuto.
  return url.includes("/functions/v1/")
    ? SUPABASE_FUNCTION_TIMEOUT_MS
    : SUPABASE_REST_TIMEOUT_MS;
}

function fetchWithTimeout(input: RequestInfo | URL, init?: RequestInit) {
  const timeoutMs = getRequestTimeout(input);
  const controller = new AbortController();
  const upstreamSignal = init?.signal;
  let removeUpstreamAbortListener: (() => void) | null = null;
  const timeoutId = window.setTimeout(() => {
    controller.abort(new DOMException(`Supabase request timeout after ${timeoutMs}ms`, "TimeoutError"));
  }, timeoutMs);

  if (upstreamSignal) {
    if (upstreamSignal.aborted) {
      controller.abort(upstreamSignal.reason);
    } else {
      const abortFromUpstream = () => controller.abort(upstreamSignal.reason);
      upstreamSignal.addEventListener("abort", abortFromUpstream, { once: true });
      removeUpstreamAbortListener = () => {
        upstreamSignal.removeEventListener("abort", abortFromUpstream);
      };
    }
  }

  return fetch(input, { ...init, signal: controller.signal }).finally(() => {
    window.clearTimeout(timeoutId);
    removeUpstreamAbortListener?.();
  });
}

function urlDi(input: RequestInfo | URL): string {
  return typeof input === "string" ? input : input instanceof URL ? input.toString() : input.url;
}

/**
 * Gli errori del database arrivano all'utente in italiano, da un punto solo.
 *
 * PostgREST risponde ai vincoli violati con il messaggio inglese di Postgres
 * ("update or delete on table … violates foreign key constraint …") e in giro
 * per l'app ci sono centinaia di `toast.error(e.message)` che lo mostrano
 * tale e quale. Qui il corpo dell'errore viene riscritto prima che
 * supabase-js lo legga: `message` in italiano, originale in `details`,
 * `code` intatto. Solo per le chiamate REST/RPC e solo per i messaggi che
 * sono davvero di Postgres (vedi traduciErrorePostgrest); auth, storage ed
 * edge function non vengono toccati.
 */
async function fetchTraducendoGliErrori(input: RequestInfo | URL, init?: RequestInit): Promise<Response> {
  const res = await fetchWithTimeout(input, init);
  if (res.ok) return res;
  if (!urlDi(input).includes("/rest/v1/")) return res;
  if (!(res.headers.get("content-type") ?? "").includes("application/json")) return res;

  let corpo: unknown;
  try {
    corpo = await res.clone().json();
  } catch {
    return res;
  }
  const tradotto = traduciErrorePostgrest(corpo);
  if (!tradotto) return res;

  // Il corpo cambia lunghezza: via gli header che descrivevano quello vecchio.
  const headers = new Headers(res.headers);
  headers.delete("content-length");
  headers.delete("content-encoding");
  return new Response(JSON.stringify(tradotto), { status: res.status, statusText: res.statusText, headers });
}

export const supabase = createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
  global: {
    fetch: fetchTraducendoGliErrori,
  },
  auth: {
    // La sessione sta in un cookie sul dominio comune, non nella memoria del
    // singolo sito: app.* e admin.* sono due origini diverse, e chi faceva
    // login sull'una la mattina dopo lo rifaceva sull'altra. Vedi authStorage.
    storage: authStorage,
    persistSession: true,
    autoRefreshToken: true,
  }
});
